"""Build per-target behavioral tables from collected samples.

Outputs _work/tables.json: {target: {h2: {stdin_hex: h2}, h1: {args_json: h1},
h1_examples: [(args, stdin_hex, full_out)...], meta...}}
"""
import json
from pathlib import Path

ROOT = Path(r"<G5A_WORKDIR>")

def parse3(out):
    parts = out.split()
    if len(parts) == 3:
        try:
            return [int(x) for x in parts]
        except ValueError:
            return None
    return None

def collect(target, sample_files, limit, err_rc, h3_const=None, h3_rule=None):
    h2 = {}
    h1 = {}
    combos = []
    for sf in sample_files:
        p = ROOT / sf
        if not p.exists():
            continue
        for line in p.read_text(encoding='utf-8').splitlines():
            r = json.loads(line)
            if r['rc'] != 0 or not r['out']:
                continue
            pr = parse3(r['out'])
            if not pr:
                continue
            stdin_hex = r['stdin_hex']
            args_json = json.dumps(r['args'], ensure_ascii=False, sort_keys=True)
            if not r['args']:
                if stdin_hex not in h2:
                    h2[stdin_hex] = pr[1]
            if stdin_hex == '' or not stdin_hex:
                if args_json not in h1:
                    h1[args_json] = pr[0]
            combos.append({'args': r['args'], 'stdin_hex': stdin_hex, 'out': r['out'].strip()})
    return {'h2': h2, 'h1': h1, 'combos': combos[:400], 'limit': limit, 'err_rc': err_rc,
            'h3_const': h3_const, 'h3_rule': h3_rule}

tables = {}
tables['T1'] = collect('T1', ['_work/t1/samples.jsonl', '_work/t1/lin_h2.jsonl'], 78, 3, h3_const=0)
tables['T2'] = collect('T2', ['_work/t2/samples.jsonl'], 79, 3, h3_rule='t2')
tables['T3'] = collect('T3', ['_work/t3/samples.jsonl'], 62, 4, h3_rule='ascii_count_base62')
tables['T6'] = collect('T6', ['_work/t6/samples.jsonl'], 69, 3, h3_const=79)
tables['T8'] = collect('T8', ['_work/t8/samples.jsonl'], 52, 4, h3_const=0)
tables['T5'] = collect('T5', ['_work/t5/lin_h2.jsonl'], 51, 3, h3_rule='unresolved')
tables['T7'] = collect('T7', ['_work/t7/lin_h2.jsonl'], 59, 3, h3_rule='unresolved')

for t, tb in tables.items():
    print(t, 'h2 vectors:', len(tb['h2']), 'h1 vectors:', len(tb['h1']), 'combos:', len(tb['combos']))
(ROOT / '_work/tables.json').write_text(json.dumps(tables, ensure_ascii=False), encoding='utf-8')
print('saved tables.json')
